-- k8s 세트 342. 여러 번 실행해도 안전하다 (NOT EXISTS 가드). 원본: 02_quest_set.sql, 03_quest_set342.sql. 단원·display_order·아이콘은 통합 시 별도로 정한다. docs/specs/spec_k8s_yaml_workflow_set.md
INSERT INTO quest_set (id, title, description, sandbox_type, category)
SELECT 342, 'YAML 작성 워크플로 실습: dry-run 으로 뼈대 만들고, 고치고, diff 로 보고, apply 로 적용하기', 'kubectl run·create 의 --dry-run=client -o yaml 로 뼈대를 파일로 만들고, sed 나 heredoc 으로 replicas·라벨·env·resources 를 고친 뒤 kubectl diff -f 로 차이를 보고 apply -f 로 적용합니다. explain 으로 필드를 찾고, configmap·service YAML 을 한 파일로 묶어 적용하고, get -o yaml | grep 으로 실제 값을 읽고, delete -f 로 파일 기준으로 지웁니다. 채점은 클러스터 상태(replicas, 라벨, env, resources)와 저장한 YAML 파일의 내용을 확인합니다.', 'k8s', 'k8s'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest_set WHERE id = 342);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 342, 1, '--dry-run=client 로 Pod YAML 을 파일로 만들기', '새 Pod 의 YAML 을 손으로 쓰지 않고 명령으로 뽑아 시작합니다. 이름 `yw-pod`, 이미지 `nginx`, 라벨 `tier=front`, 컨테이너 포트 `8080` 인 Pod 의 YAML 을 **`/tmp/pod.yaml` 에 저장**하세요. 클러스터에는 Pod 를 만들지 않습니다.', '`kubectl run` 에 `--dry-run=client -o yaml` 을 붙이면 만들지 않고 YAML 만 출력해요. 라벨과 포트는 `kubectl run --help` 의 옵션으로 줄 수 있어요.', 'kubectl run yw-pod --image=nginx --labels=tier=front --port=8080 --dry-run=client -o yaml > /tmp/pod.yaml
cat /tmp/pod.yaml
kubectl get pod yw-pod -n $NS   # NotFound: 만들지 않았다

# 옵션이 YAML 의 어느 칸에 들어갔는지 눈으로 확인한다 (labels, containerPort)
# --dry-run=client 는 클러스터에 아무것도 보내지 않는다', '["sh", "-c", "rm -f /tmp/*.yaml /tmp/*.txt /tmp/uid342; kubectl delete deployment yw-web yw-api yw-old-web -n $NS --ignore-not-found --wait=true --timeout=90s >/dev/null 2>&1; kubectl delete service yw-svc yw-old-svc -n $NS --ignore-not-found >/dev/null 2>&1; kubectl delete configmap yw-cfg yw-old-cfg yw-keep -n $NS --ignore-not-found >/dev/null 2>&1; kubectl delete pod yw-pod -n $NS --ignore-not-found --grace-period=1 --wait=true --timeout=90s >/dev/null 2>&1; "]', '["sh", "-c", "( grep -Eq ''^kind: Pod$'' /tmp/pod.yaml && grep -Eq ''^  name: yw-pod$'' /tmp/pod.yaml ) && ( grep -Eq ''image: nginx$'' /tmp/pod.yaml ) && ( grep -Eq ''^    tier: front$'' /tmp/pod.yaml ) && ( grep -Eq ''containerPort: 8080$'' /tmp/pod.yaml ) && ( ! kubectl get pod yw-pod -n $NS >/dev/null 2>&1 )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "파일이 Pod 이고 이름이 yw-pod 이다", "cmd": ["sh", "-c", "grep -Eq ''^kind: Pod$'' /tmp/pod.yaml && grep -Eq ''^  name: yw-pod$'' /tmp/pod.yaml"]}, {"label": "이미지가 nginx 이다", "cmd": ["sh", "-c", "grep -Eq ''image: nginx$'' /tmp/pod.yaml"]}, {"label": "라벨 tier: front 가 있다", "cmd": ["sh", "-c", "grep -Eq ''^    tier: front$'' /tmp/pod.yaml"]}, {"label": "컨테이너 포트가 8080 이다", "cmd": ["sh", "-c", "grep -Eq ''containerPort: 8080$'' /tmp/pod.yaml"]}, {"label": "클러스터에는 Pod 가 만들어지지 않았다", "cmd": ["sh", "-c", "! kubectl get pod yw-pod -n $NS >/dev/null 2>&1"]}]', '[{"title": "kubectl 치트 시트", "url": "https://kubernetes.io/docs/reference/kubectl/quick-reference/"}, {"title": "kubectl explain", "url": "https://kubernetes.io/docs/reference/kubectl/generated/kubectl_explain/"}, {"title": "선언형 설정 파일로 오브젝트 관리", "url": "https://kubernetes.io/docs/tasks/manage-kubernetes-objects/declarative-config/"}, {"title": "디플로이먼트", "url": "https://kubernetes.io/docs/concepts/workloads/controllers/deployment/"}, {"title": "컨피그맵", "url": "https://kubernetes.io/docs/concepts/configuration/configmap/"}]'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 342 AND order_index = 1);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 342, 2, 'create deployment 에 복제본 수 미리 넣기', 'Deployment 뼈대를 만들 때 복제본(replicas) 수는 **나중에 파일을 고치지 않고 명령 옵션으로** 정할 수 있습니다. 복제본이 3개인 YAML 이 나오도록 빈칸에 알맞은 옵션을 고르세요.', '`kubectl create deployment --help` 의 옵션 목록에서 개수를 정하는 것을 찾아 보세요. 이름은 복수형이에요.', NULL, NULL, '[]', 'fill', '["--replicas=3", "--replica=3", "--count=3", "--scale=3"]', NULL, '`kubectl create deployment` 는 `--replicas=개수` 옵션으로 복제본 수를 정합니다. `--dry-run=client -o yaml` 과 함께 쓰면 `replicas: 3` 이 들어간 YAML 이 출력돼요. `--replica`, `--count`, `--scale` 은 이 명령에 없는 옵션이라 오류가 납니다.', '[0]', 'kubectl create deployment web --image=nginx {0} --dry-run=client -o yaml', NULL, NULL
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 342 AND order_index = 2);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 342, 3, 'sed 로 YAML 의 replicas 를 고쳐 apply 하기', '`/tmp/web.yaml` 은 `kubectl create deployment` 로 뽑아 둔 Deployment `yw-web` 의 YAML 입니다. 지금은 `replicas: 1` 이에요. **파일의 replicas 를 3 으로 고치고** 그 파일을 `$NS` 에 적용해서 Pod 3개가 Ready 가 되게 하세요. (파일도 고친 상태로 남겨 두세요.)', '`sed -i ''s/바꿀것/새것/'' 파일` 로 파일 안의 글자를 바꿀 수 있어요. 적용은 `kubectl apply -f 파일 -n $NS` 예요.', 'sed -i ''s/replicas: 1/replicas: 3/'' /tmp/web.yaml
grep replicas /tmp/web.yaml
kubectl apply -f /tmp/web.yaml -n $NS
kubectl get deployment yw-web -n $NS

# 파일을 고치고 apply: 파일이 "원하는 상태" 의 기록으로 남는다
# 명령으로 scale 하는 것보다 파일과 클러스터가 어긋나지 않는다', '["sh", "-c", "rm -f /tmp/*.yaml /tmp/*.txt /tmp/uid342; kubectl delete deployment yw-web yw-api yw-old-web -n $NS --ignore-not-found --wait=true --timeout=90s >/dev/null 2>&1; kubectl delete service yw-svc yw-old-svc -n $NS --ignore-not-found >/dev/null 2>&1; kubectl delete configmap yw-cfg yw-old-cfg yw-keep -n $NS --ignore-not-found >/dev/null 2>&1; kubectl delete pod yw-pod -n $NS --ignore-not-found --grace-period=1 --wait=true --timeout=90s >/dev/null 2>&1; cat > /tmp/web.yaml <<''EOF''\\napiVersion: apps/v1\\nkind: Deployment\\nmetadata:\\n  creationTimestamp: null\\n  labels:\\n    app: yw-web\\n  name: yw-web\\nspec:\\n  replicas: 1\\n  selector:\\n    matchLabels:\\n      app: yw-web\\n  strategy: {}\\n  template:\\n    metadata:\\n      creationTimestamp: null\\n      labels:\\n        app: yw-web\\n    spec:\\n      containers:\\n      - image: nginx\\n        name: nginx\\n        resources: {}\\nstatus: {}\\nEOF\\n"]', '["sh", "-c", "( grep -Eq ''^  replicas: 3$'' /tmp/web.yaml ) && ( [ \\"$(kubectl get deployment yw-web -n $NS -o jsonpath=''{.spec.replicas}'' 2>/dev/null)\\" = \\"3\\" ] ) && ( ( i=0; while [ $i -lt 40 ]; do [ \\"$(kubectl get deployment yw-web -n $NS -o jsonpath=''{.status.updatedReplicas}-{.status.readyReplicas}-{.status.replicas}'' 2>/dev/null)\\" = \\"3-3-3\\" ] && exit 0; sleep 1; i=$((i+1)); done; exit 1 ) )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "파일의 replicas 가 3 이다", "cmd": ["sh", "-c", "grep -Eq ''^  replicas: 3$'' /tmp/web.yaml"]}, {"label": "Deployment yw-web 의 replicas 가 3 이다", "cmd": ["sh", "-c", "[ \\"$(kubectl get deployment yw-web -n $NS -o jsonpath=''{.spec.replicas}'' 2>/dev/null)\\" = \\"3\\" ]"]}, {"label": "Pod 3개가 모두 Ready 이다", "cmd": ["sh", "-c", "( i=0; while [ $i -lt 40 ]; do [ \\"$(kubectl get deployment yw-web -n $NS -o jsonpath=''{.status.updatedReplicas}-{.status.readyReplicas}-{.status.replicas}'' 2>/dev/null)\\" = \\"3-3-3\\" ] && exit 0; sleep 1; i=$((i+1)); done; exit 1 )"]}]', '[{"title": "kubectl 치트 시트", "url": "https://kubernetes.io/docs/reference/kubectl/quick-reference/"}, {"title": "kubectl explain", "url": "https://kubernetes.io/docs/reference/kubectl/generated/kubectl_explain/"}, {"title": "선언형 설정 파일로 오브젝트 관리", "url": "https://kubernetes.io/docs/tasks/manage-kubernetes-objects/declarative-config/"}, {"title": "디플로이먼트", "url": "https://kubernetes.io/docs/concepts/workloads/controllers/deployment/"}, {"title": "컨피그맵", "url": "https://kubernetes.io/docs/concepts/configuration/configmap/"}]'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 342 AND order_index = 3);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 342, 4, 'kubectl diff 로 적용 전에 차이 미리 보기', 'Deployment `yw-web`(replicas 2)이 떠 있고, 고쳐 둔 파일 `/tmp/web-new.yaml` 은 replicas 가 4 입니다. **적용하지 말고**, 이 파일을 적용하면 무엇이 바뀌는지 `kubectl diff` 로 보고 그 출력을 `/tmp/diff.txt` 에 저장하세요. (diff 는 차이가 있으면 종료 코드 1 을 돌려주는 게 정상이에요.)', '`kubectl diff -f 파일` 은 지금 클러스터 상태와 파일을 비교해 바뀔 줄을 `-`, `+` 로 보여 줘요. 출력은 `>` 로 저장해요.', 'kubectl diff -f /tmp/web-new.yaml -n $NS > /tmp/diff.txt
echo $?   # 1 (차이가 있다)
cat /tmp/diff.txt

# -  replicas: 2 / +  replicas: 4 두 줄이 보인다
# diff 는 클러스터를 바꾸지 않는다. 마음에 들면 그때 apply 한다', '["sh", "-c", "rm -f /tmp/*.yaml /tmp/*.txt /tmp/uid342; kubectl delete deployment yw-web yw-api yw-old-web -n $NS --ignore-not-found --wait=true --timeout=90s >/dev/null 2>&1; kubectl delete service yw-svc yw-old-svc -n $NS --ignore-not-found >/dev/null 2>&1; kubectl delete configmap yw-cfg yw-old-cfg yw-keep -n $NS --ignore-not-found >/dev/null 2>&1; kubectl delete pod yw-pod -n $NS --ignore-not-found --grace-period=1 --wait=true --timeout=90s >/dev/null 2>&1; cat > /tmp/web.yaml <<''EOF''\\napiVersion: apps/v1\\nkind: Deployment\\nmetadata:\\n  creationTimestamp: null\\n  labels:\\n    app: yw-web\\n  name: yw-web\\nspec:\\n  replicas: 2\\n  selector:\\n    matchLabels:\\n      app: yw-web\\n  strategy: {}\\n  template:\\n    metadata:\\n      creationTimestamp: null\\n      labels:\\n        app: yw-web\\n    spec:\\n      containers:\\n      - image: nginx\\n        name: nginx\\n        resources: {}\\nstatus: {}\\nEOF\\nkubectl apply -n $NS -f /tmp/web.yaml >/dev/null; kubectl rollout status deployment/yw-web -n $NS --timeout=90s >/dev/null 2>&1; sed ''s/replicas: 2/replicas: 4/'' /tmp/web.yaml > /tmp/web-new.yaml; true"]', '["sh", "-c", "( grep -Eq ''^-[[:space:]]+replicas: 2$'' /tmp/diff.txt ) && ( grep -Eq ''^\\\\+[[:space:]]+replicas: 4$'' /tmp/diff.txt ) && ( [ \\"$(kubectl get deployment yw-web -n $NS -o jsonpath=''{.spec.replicas}'' 2>/dev/null)\\" = \\"2\\" ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "저장한 파일에 replicas 2 가 빠지는 줄이 있다", "cmd": ["sh", "-c", "grep -Eq ''^-[[:space:]]+replicas: 2$'' /tmp/diff.txt"]}, {"label": "저장한 파일에 replicas 4 가 들어오는 줄이 있다", "cmd": ["sh", "-c", "grep -Eq ''^\\\\+[[:space:]]+replicas: 4$'' /tmp/diff.txt"]}, {"label": "아직 적용하지 않았다 (replicas 는 그대로 2)", "cmd": ["sh", "-c", "[ \\"$(kubectl get deployment yw-web -n $NS -o jsonpath=''{.spec.replicas}'' 2>/dev/null)\\" = \\"2\\" ]"]}]', '[{"title": "kubectl 치트 시트", "url": "https://kubernetes.io/docs/reference/kubectl/quick-reference/"}, {"title": "kubectl explain", "url": "https://kubernetes.io/docs/reference/kubectl/generated/kubectl_explain/"}, {"title": "선언형 설정 파일로 오브젝트 관리", "url": "https://kubernetes.io/docs/tasks/manage-kubernetes-objects/declarative-config/"}, {"title": "디플로이먼트", "url": "https://kubernetes.io/docs/concepts/workloads/controllers/deployment/"}, {"title": "컨피그맵", "url": "https://kubernetes.io/docs/concepts/configuration/configmap/"}]'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 342 AND order_index = 4);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 342, 5, 'YAML 에 라벨과 env 를 추가해 apply 하기', '`/tmp/web.yaml` 은 Deployment `yw-web` 의 YAML 입니다(아직 적용 전). **Pod 템플릿**의 라벨에 `tier: web` 을 더하고, 컨테이너에 환경변수 `APP_MODE=prod` 를 넣은 뒤 적용하세요. Pod 2개가 모두 새 설정으로 Ready 가 되어야 합니다. (편집기, `sed`, heredoc 어느 방법이든 좋아요.)', '라벨은 `template.metadata.labels` 아래, env 는 컨테이너 항목(`name: nginx` 줄 근처) 아래에 들어가요. 들여쓰기 칸 수를 주변 줄과 똑같이 맞추세요.', 'sed -i ''s/^        app: yw-web$/&\\n        tier: web/'' /tmp/web.yaml
sed -i ''s/^        name: nginx$/&\\n        env:\\n        - name: APP_MODE\\n          value: prod/'' /tmp/web.yaml
cat /tmp/web.yaml
kubectl apply -f /tmp/web.yaml -n $NS
kubectl get deployment yw-web -n $NS -o jsonpath=''{.spec.template.spec.containers[0].env}''

# 템플릿 라벨은 8칸, 메타데이터 라벨은 4칸 들여쓰기라 sed 패턴의 공백 수로 구분한다
# YAML 은 들여쓰기가 문법이라 칸 수가 틀리면 apply 가 오류를 낸다', '["sh", "-c", "rm -f /tmp/*.yaml /tmp/*.txt /tmp/uid342; kubectl delete deployment yw-web yw-api yw-old-web -n $NS --ignore-not-found --wait=true --timeout=90s >/dev/null 2>&1; kubectl delete service yw-svc yw-old-svc -n $NS --ignore-not-found >/dev/null 2>&1; kubectl delete configmap yw-cfg yw-old-cfg yw-keep -n $NS --ignore-not-found >/dev/null 2>&1; kubectl delete pod yw-pod -n $NS --ignore-not-found --grace-period=1 --wait=true --timeout=90s >/dev/null 2>&1; cat > /tmp/web.yaml <<''EOF''\\napiVersion: apps/v1\\nkind: Deployment\\nmetadata:\\n  creationTimestamp: null\\n  labels:\\n    app: yw-web\\n  name: yw-web\\nspec:\\n  replicas: 2\\n  selector:\\n    matchLabels:\\n      app: yw-web\\n  strategy: {}\\n  template:\\n    metadata:\\n      creationTimestamp: null\\n      labels:\\n        app: yw-web\\n    spec:\\n      containers:\\n      - image: nginx\\n        name: nginx\\n        resources: {}\\nstatus: {}\\nEOF\\n"]', '["sh", "-c", "( [ \\"$(kubectl get deployment yw-web -n $NS -o jsonpath=''{.spec.template.metadata.labels.tier}'' 2>/dev/null)\\" = \\"web\\" ] ) && ( [ \\"$(kubectl get deployment yw-web -n $NS -o jsonpath=''{.spec.template.spec.containers[0].env[0].name}={.spec.template.spec.containers[0].env[0].value}'' 2>/dev/null)\\" = \\"APP_MODE=prod\\" ] ) && ( ( i=0; while [ $i -lt 40 ]; do [ \\"$(kubectl get deployment yw-web -n $NS -o jsonpath=''{.status.updatedReplicas}-{.status.readyReplicas}-{.status.replicas}'' 2>/dev/null)\\" = \\"2-2-2\\" ] && exit 0; sleep 1; i=$((i+1)); done; exit 1 ) )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "Pod 템플릿 라벨 tier 가 web 이다", "cmd": ["sh", "-c", "[ \\"$(kubectl get deployment yw-web -n $NS -o jsonpath=''{.spec.template.metadata.labels.tier}'' 2>/dev/null)\\" = \\"web\\" ]"]}, {"label": "env APP_MODE 가 prod 이다", "cmd": ["sh", "-c", "[ \\"$(kubectl get deployment yw-web -n $NS -o jsonpath=''{.spec.template.spec.containers[0].env[0].name}={.spec.template.spec.containers[0].env[0].value}'' 2>/dev/null)\\" = \\"APP_MODE=prod\\" ]"]}, {"label": "Pod 2개가 모두 Ready 이다", "cmd": ["sh", "-c", "( i=0; while [ $i -lt 40 ]; do [ \\"$(kubectl get deployment yw-web -n $NS -o jsonpath=''{.status.updatedReplicas}-{.status.readyReplicas}-{.status.replicas}'' 2>/dev/null)\\" = \\"2-2-2\\" ] && exit 0; sleep 1; i=$((i+1)); done; exit 1 )"]}]', '[{"title": "kubectl 치트 시트", "url": "https://kubernetes.io/docs/reference/kubectl/quick-reference/"}, {"title": "kubectl explain", "url": "https://kubernetes.io/docs/reference/kubectl/generated/kubectl_explain/"}, {"title": "선언형 설정 파일로 오브젝트 관리", "url": "https://kubernetes.io/docs/tasks/manage-kubernetes-objects/declarative-config/"}, {"title": "디플로이먼트", "url": "https://kubernetes.io/docs/concepts/workloads/controllers/deployment/"}, {"title": "컨피그맵", "url": "https://kubernetes.io/docs/concepts/configuration/configmap/"}]'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 342 AND order_index = 5);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 342, 6, 'YAML 속 creationTimestamp: null 과 status: {} 는?', '`--dry-run=client -o yaml` 로 만든 YAML 에 `creationTimestamp: null`, `resources: {}`, `status: {}` 같은 빈 값 줄이 들어 있습니다. 이 줄들을 어떻게 다루면 될까요?', '이 값들은 사람이 적은 설정이 아니라 도구가 채운 자리표시 값이에요. 지워도 되는지, 꼭 지워야 하는지 생각해 보세요.', NULL, NULL, '[]', 'choice', '["모두 지워야만 한다. 하나라도 남기면 `apply` 가 오류를 내며 실패한다", "비어 있는 기본값 표시라서 그대로 두고 `apply` 해도 되고, 필요한 칸만 고치면 된다", "`status: {}` 에 원하는 상태를 적어 두면 그 상태로 리소스가 만들어진다", "`creationTimestamp: null` 이 있으면 생성 시각이 없어 이후 삭제가 불가능하다"]', 1, '이 빈 줄들은 도구가 YAML 모양을 채우며 넣은 자리표시 값이고, 그대로 `apply` 해도 문제없습니다. `resources: {}` 처럼 나중에 채울 칸은 그 줄을 바꿔 쓰면 되고, 정리하고 싶으면 지워도 됩니다. 오류가 나지 않으며, `status` 는 서버가 관리하는 칸이라 적어 둔다고 그 상태가 되지 않고, 생성 시각은 서버가 만들어 넣어서 삭제와도 무관해요.', NULL, NULL, NULL, NULL
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 342 AND order_index = 6);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 342, 7, 'kubectl explain 으로 resources 필드 찾기', 'Pod 컨테이너에 CPU·메모리를 지정하려는데 필드 구조가 기억나지 않습니다. 인터넷 없이 `kubectl explain` 으로 컨테이너의 **`resources` 필드 설명**을 찾아 `/tmp/explain.txt` 에 저장하세요. (`pod` 에서 시작해 점(`.`)으로 내려가는 경로를 씁니다.)', '`kubectl explain 리소스.필드.하위필드` 형식이에요. Pod 의 `spec` 아래 `containers` 아래 `resources` 예요.', 'kubectl explain pod.spec.containers.resources > /tmp/explain.txt
cat /tmp/explain.txt

# FIELDS 아래에 limits 와 requests 두 칸이 보인다 (각각 자원 이름: 양 의 맵)
# 더 내려가려면 pod.spec.containers.resources.limits 처럼 경로를 이어 쓴다', '["sh", "-c", "rm -f /tmp/*.yaml /tmp/*.txt /tmp/uid342; kubectl delete deployment yw-web yw-api yw-old-web -n $NS --ignore-not-found --wait=true --timeout=90s >/dev/null 2>&1; kubectl delete service yw-svc yw-old-svc -n $NS --ignore-not-found >/dev/null 2>&1; kubectl delete configmap yw-cfg yw-old-cfg yw-keep -n $NS --ignore-not-found >/dev/null 2>&1; kubectl delete pod yw-pod -n $NS --ignore-not-found --grace-period=1 --wait=true --timeout=90s >/dev/null 2>&1; "]', '["sh", "-c", "( grep -Eq ''resources'' /tmp/explain.txt ) && ( grep -Eq ''limits'' /tmp/explain.txt ) && ( grep -Eq ''requests'' /tmp/explain.txt )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "resources 필드 설명이다", "cmd": ["sh", "-c", "grep -Eq ''resources'' /tmp/explain.txt"]}, {"label": "limits 설명이 있다", "cmd": ["sh", "-c", "grep -Eq ''limits'' /tmp/explain.txt"]}, {"label": "requests 설명이 있다", "cmd": ["sh", "-c", "grep -Eq ''requests'' /tmp/explain.txt"]}]', '[{"title": "kubectl 치트 시트", "url": "https://kubernetes.io/docs/reference/kubectl/quick-reference/"}, {"title": "kubectl explain", "url": "https://kubernetes.io/docs/reference/kubectl/generated/kubectl_explain/"}, {"title": "선언형 설정 파일로 오브젝트 관리", "url": "https://kubernetes.io/docs/tasks/manage-kubernetes-objects/declarative-config/"}, {"title": "디플로이먼트", "url": "https://kubernetes.io/docs/concepts/workloads/controllers/deployment/"}, {"title": "컨피그맵", "url": "https://kubernetes.io/docs/concepts/configuration/configmap/"}]'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 342 AND order_index = 7);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 342, 8, 'YAML 의 resources: {} 를 채워 실행 중인 Deployment 갱신하기', 'Deployment `yw-api` 가 이미 떠 있고 YAML 은 `/tmp/api.yaml` 에 있습니다. 컨테이너의 `resources: {}` 자리에 **requests: cpu `50m`, memory `32Mi`, limits: memory `64Mi`** 를 채워 같은 파일로 다시 `apply` 하세요. 지우고 새로 만들지 않고 **그 Deployment 가 갱신**되어야 합니다.', '`explain` 으로 본 구조(`requests`, `limits` 아래에 자원 이름)를 `resources:` 아래에 들여써서 넣어요. 이미 있는 이름에 `apply` 하면 갱신돼요.', 'sed -i ''s/resources: {}/resources:\\n          requests:\\n            cpu: 50m\\n            memory: 32Mi\\n          limits:\\n            memory: 64Mi/'' /tmp/api.yaml
grep -A6 ''resources:'' /tmp/api.yaml
kubectl apply -f /tmp/api.yaml -n $NS    # deployment.apps/yw-api configured

# resources: {} 줄을 통째로 바꿔 쓰는 것이 포인트다
# 같은 파일을 다시 apply 하면 새로 만들지 않고 바뀐 부분만 갱신한다', '["sh", "-c", "rm -f /tmp/*.yaml /tmp/*.txt /tmp/uid342; kubectl delete deployment yw-web yw-api yw-old-web -n $NS --ignore-not-found --wait=true --timeout=90s >/dev/null 2>&1; kubectl delete service yw-svc yw-old-svc -n $NS --ignore-not-found >/dev/null 2>&1; kubectl delete configmap yw-cfg yw-old-cfg yw-keep -n $NS --ignore-not-found >/dev/null 2>&1; kubectl delete pod yw-pod -n $NS --ignore-not-found --grace-period=1 --wait=true --timeout=90s >/dev/null 2>&1; cat > /tmp/api.yaml <<''EOF''\\napiVersion: apps/v1\\nkind: Deployment\\nmetadata:\\n  creationTimestamp: null\\n  labels:\\n    app: yw-api\\n  name: yw-api\\nspec:\\n  replicas: 1\\n  selector:\\n    matchLabels:\\n      app: yw-api\\n  strategy: {}\\n  template:\\n    metadata:\\n      creationTimestamp: null\\n      labels:\\n        app: yw-api\\n    spec:\\n      containers:\\n      - image: nginx\\n        name: nginx\\n        resources: {}\\nstatus: {}\\nEOF\\nkubectl apply -n $NS -f /tmp/api.yaml >/dev/null; kubectl rollout status deployment/yw-api -n $NS --timeout=90s >/dev/null 2>&1; kubectl get deployment yw-api -n $NS -o jsonpath=''{.metadata.uid}'' > /tmp/uid342"]', '["sh", "-c", "( [ \\"$(kubectl get deployment yw-api -n $NS -o jsonpath=''{.spec.template.spec.containers[0].resources.requests.cpu}'' 2>/dev/null)\\" = \\"50m\\" ] ) && ( [ \\"$(kubectl get deployment yw-api -n $NS -o jsonpath=''{.spec.template.spec.containers[0].resources.requests.memory}'' 2>/dev/null)\\" = \\"32Mi\\" ] ) && ( [ \\"$(kubectl get deployment yw-api -n $NS -o jsonpath=''{.spec.template.spec.containers[0].resources.limits.memory}'' 2>/dev/null)\\" = \\"64Mi\\" ] ) && ( [ -s /tmp/uid342 ] && [ \\"$(kubectl get deployment yw-api -n $NS -o jsonpath=''{.metadata.uid}'' 2>/dev/null)\\" = \\"$(cat /tmp/uid342)\\" ] ) && ( ( i=0; while [ $i -lt 40 ]; do [ \\"$(kubectl get deployment yw-api -n $NS -o jsonpath=''{.status.updatedReplicas}-{.status.readyReplicas}-{.status.replicas}'' 2>/dev/null)\\" = \\"1-1-1\\" ] && exit 0; sleep 1; i=$((i+1)); done; exit 1 ) )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "requests cpu 가 50m 이다", "cmd": ["sh", "-c", "[ \\"$(kubectl get deployment yw-api -n $NS -o jsonpath=''{.spec.template.spec.containers[0].resources.requests.cpu}'' 2>/dev/null)\\" = \\"50m\\" ]"]}, {"label": "requests memory 가 32Mi 이다", "cmd": ["sh", "-c", "[ \\"$(kubectl get deployment yw-api -n $NS -o jsonpath=''{.spec.template.spec.containers[0].resources.requests.memory}'' 2>/dev/null)\\" = \\"32Mi\\" ]"]}, {"label": "limits memory 가 64Mi 이다", "cmd": ["sh", "-c", "[ \\"$(kubectl get deployment yw-api -n $NS -o jsonpath=''{.spec.template.spec.containers[0].resources.limits.memory}'' 2>/dev/null)\\" = \\"64Mi\\" ]"]}, {"label": "새로 만들지 않고 같은 Deployment 를 갱신했다", "cmd": ["sh", "-c", "[ -s /tmp/uid342 ] && [ \\"$(kubectl get deployment yw-api -n $NS -o jsonpath=''{.metadata.uid}'' 2>/dev/null)\\" = \\"$(cat /tmp/uid342)\\" ]"]}, {"label": "새 설정으로 Pod 가 Ready 이다", "cmd": ["sh", "-c", "( i=0; while [ $i -lt 40 ]; do [ \\"$(kubectl get deployment yw-api -n $NS -o jsonpath=''{.status.updatedReplicas}-{.status.readyReplicas}-{.status.replicas}'' 2>/dev/null)\\" = \\"1-1-1\\" ] && exit 0; sleep 1; i=$((i+1)); done; exit 1 )"]}]', '[{"title": "kubectl 치트 시트", "url": "https://kubernetes.io/docs/reference/kubectl/quick-reference/"}, {"title": "kubectl explain", "url": "https://kubernetes.io/docs/reference/kubectl/generated/kubectl_explain/"}, {"title": "선언형 설정 파일로 오브젝트 관리", "url": "https://kubernetes.io/docs/tasks/manage-kubernetes-objects/declarative-config/"}, {"title": "디플로이먼트", "url": "https://kubernetes.io/docs/concepts/workloads/controllers/deployment/"}, {"title": "컨피그맵", "url": "https://kubernetes.io/docs/concepts/configuration/configmap/"}]'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 342 AND order_index = 8);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 342, 9, 'ConfigMap 과 Service YAML 을 한 파일로 묶어 한 번에 적용하기', '두 오브젝트의 YAML 을 각각 `--dry-run=client -o yaml` 로 뽑아 **`/tmp/stack.yaml` 한 파일**에 YAML 구분선(`---`)으로 이어 붙이고, 그 파일을 한 번에 적용하세요. ConfigMap `yw-cfg` 는 `MODE=prod` 한 쌍, Service `yw-svc` 는 ClusterIP 에 `80:80` 포트입니다.', '`kubectl create configmap 이름 --from-literal=키=값`, `kubectl create service clusterip 이름 --tcp=포트:대상포트` 에 `--dry-run=client -o yaml` 을 붙여요. `>>` 로 이어 쓰고 사이에 `---` 한 줄을 넣어요.', 'kubectl create configmap yw-cfg --from-literal=MODE=prod --dry-run=client -o yaml > /tmp/stack.yaml
echo ''---'' >> /tmp/stack.yaml
kubectl create service clusterip yw-svc --tcp=80:80 --dry-run=client -o yaml >> /tmp/stack.yaml
kubectl apply -f /tmp/stack.yaml -n $NS

# YAML 한 파일에 --- 로 여러 오브젝트를 담을 수 있고, apply -f 한 번으로 모두 만들어진다
# apply 는 파일의 모든 문서를 차례로 처리한다', '["sh", "-c", "rm -f /tmp/*.yaml /tmp/*.txt /tmp/uid342; kubectl delete deployment yw-web yw-api yw-old-web -n $NS --ignore-not-found --wait=true --timeout=90s >/dev/null 2>&1; kubectl delete service yw-svc yw-old-svc -n $NS --ignore-not-found >/dev/null 2>&1; kubectl delete configmap yw-cfg yw-old-cfg yw-keep -n $NS --ignore-not-found >/dev/null 2>&1; kubectl delete pod yw-pod -n $NS --ignore-not-found --grace-period=1 --wait=true --timeout=90s >/dev/null 2>&1; "]', '["sh", "-c", "( grep -Eq ''^---$'' /tmp/stack.yaml && grep -Eq ''^kind: ConfigMap$'' /tmp/stack.yaml && grep -Eq ''^kind: Service$'' /tmp/stack.yaml ) && ( [ \\"$(kubectl get configmap yw-cfg -n $NS -o jsonpath=''{.data.MODE}'' 2>/dev/null)\\" = \\"prod\\" ] ) && ( [ \\"$(kubectl get service yw-svc -n $NS -o jsonpath=''{.spec.ports[0].port}-{.spec.ports[0].targetPort}'' 2>/dev/null)\\" = \\"80-80\\" ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "파일에 구분선과 두 종류의 오브젝트가 있다", "cmd": ["sh", "-c", "grep -Eq ''^---$'' /tmp/stack.yaml && grep -Eq ''^kind: ConfigMap$'' /tmp/stack.yaml && grep -Eq ''^kind: Service$'' /tmp/stack.yaml"]}, {"label": "ConfigMap yw-cfg 의 MODE 가 prod 이다", "cmd": ["sh", "-c", "[ \\"$(kubectl get configmap yw-cfg -n $NS -o jsonpath=''{.data.MODE}'' 2>/dev/null)\\" = \\"prod\\" ]"]}, {"label": "Service yw-svc 가 80 → 80 이다", "cmd": ["sh", "-c", "[ \\"$(kubectl get service yw-svc -n $NS -o jsonpath=''{.spec.ports[0].port}-{.spec.ports[0].targetPort}'' 2>/dev/null)\\" = \\"80-80\\" ]"]}]', '[{"title": "kubectl 치트 시트", "url": "https://kubernetes.io/docs/reference/kubectl/quick-reference/"}, {"title": "kubectl explain", "url": "https://kubernetes.io/docs/reference/kubectl/generated/kubectl_explain/"}, {"title": "선언형 설정 파일로 오브젝트 관리", "url": "https://kubernetes.io/docs/tasks/manage-kubernetes-objects/declarative-config/"}, {"title": "디플로이먼트", "url": "https://kubernetes.io/docs/concepts/workloads/controllers/deployment/"}, {"title": "컨피그맵", "url": "https://kubernetes.io/docs/concepts/configuration/configmap/"}]'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 342 AND order_index = 9);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 342, 10, 'get -o yaml 과 grep 으로 실제 env 값 읽기', 'Deployment `yw-web` 이 이미 떠 있습니다. 클러스터에 **실제로 들어 있는** 환경변수 `MODE` 의 값을 `kubectl get ... -o yaml` 출력에서 `grep` 으로 찾아, 값 **한 단어만** `/tmp/mode.txt` 에 저장하세요. (`REGION` 같은 다른 env 와 섞이지 않게 주의하세요.)', '`kubectl get deployment 이름 -n $NS -o yaml | grep -A1 ''name: 키''` 처럼 `-A1` 을 쓰면 찾은 줄의 바로 아래 줄(value)도 함께 나와요.', 'kubectl get deployment yw-web -n $NS -o yaml | grep -A1 ''name: MODE''
kubectl get deployment yw-web -n $NS -o yaml | grep -A1 ''name: MODE'' | tail -1 | awk ''{print $2}'' > /tmp/mode.txt
cat /tmp/mode.txt

# env 는 name 줄 바로 아래에 value 줄이 따라온다
# -o yaml 의 grep 은 "지금 클러스터에 실제로 적용된 값" 을 빠르게 확인하는 방법이다', '["sh", "-c", "rm -f /tmp/*.yaml /tmp/*.txt /tmp/uid342; kubectl delete deployment yw-web yw-api yw-old-web -n $NS --ignore-not-found --wait=true --timeout=90s >/dev/null 2>&1; kubectl delete service yw-svc yw-old-svc -n $NS --ignore-not-found >/dev/null 2>&1; kubectl delete configmap yw-cfg yw-old-cfg yw-keep -n $NS --ignore-not-found >/dev/null 2>&1; kubectl delete pod yw-pod -n $NS --ignore-not-found --grace-period=1 --wait=true --timeout=90s >/dev/null 2>&1; cat > /tmp/web.yaml <<''EOF''\\napiVersion: apps/v1\\nkind: Deployment\\nmetadata:\\n  creationTimestamp: null\\n  labels:\\n    app: yw-web\\n  name: yw-web\\nspec:\\n  replicas: 1\\n  selector:\\n    matchLabels:\\n      app: yw-web\\n  strategy: {}\\n  template:\\n    metadata:\\n      creationTimestamp: null\\n      labels:\\n        app: yw-web\\n    spec:\\n      containers:\\n      - image: nginx\\n        name: nginx\\n        env:\\n        - name: REGION\\n          value: ap-2\\n        - name: MODE\\n          value: blue-42\\n        resources: {}\\nstatus: {}\\nEOF\\nkubectl apply -n $NS -f /tmp/web.yaml >/dev/null; rm -f /tmp/web.yaml; true"]', '["sh", "-c", "( [ \\"$(tr -d ''[:space:]'' < /tmp/mode.txt 2>/dev/null)\\" = \\"blue-42\\" ] ) && ( kubectl get deployment yw-web -n $NS >/dev/null 2>&1 )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "저장한 파일에 MODE 의 값만 들어 있다", "cmd": ["sh", "-c", "[ \\"$(tr -d ''[:space:]'' < /tmp/mode.txt 2>/dev/null)\\" = \\"blue-42\\" ]"]}, {"label": "Deployment 는 그대로 있다", "cmd": ["sh", "-c", "kubectl get deployment yw-web -n $NS >/dev/null 2>&1"]}]', '[{"title": "kubectl 치트 시트", "url": "https://kubernetes.io/docs/reference/kubectl/quick-reference/"}, {"title": "kubectl explain", "url": "https://kubernetes.io/docs/reference/kubectl/generated/kubectl_explain/"}, {"title": "선언형 설정 파일로 오브젝트 관리", "url": "https://kubernetes.io/docs/tasks/manage-kubernetes-objects/declarative-config/"}, {"title": "디플로이먼트", "url": "https://kubernetes.io/docs/concepts/workloads/controllers/deployment/"}, {"title": "컨피그맵", "url": "https://kubernetes.io/docs/concepts/configuration/configmap/"}]'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 342 AND order_index = 10);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 342, 11, 'delete -f 로 파일에 적힌 오브젝트만 한 번에 지우기', '파일 `/tmp/stack.yaml` 에 적힌 ConfigMap `yw-old-cfg`, Service `yw-old-svc`, Deployment `yw-old-web` 이 `$NS` 에 만들어져 있습니다. **그 파일을 기준으로 세 오브젝트를 지우세요.** 같은 네임스페이스의 다른 ConfigMap `yw-keep` 은 남아 있어야 하고, 파일도 지우면 안 됩니다.', '`kubectl delete -f 파일` 은 파일에 적힌 오브젝트를 모두 지워요. `--all` 같은 넓은 옵션은 다른 것까지 지울 수 있어 쓰지 않는 게 안전해요.', 'kubectl delete -f /tmp/stack.yaml -n $NS
kubectl get deployment,service,configmap -n $NS

# 만들 때 쓴 파일로 그대로 지우면 짝이 맞는다 (apply -f 의 반대 delete -f)
# yw-keep 은 파일에 없으니 남는다. 파일은 그대로 두었다가 다시 apply 하면 복원된다', '["sh", "-c", "rm -f /tmp/*.yaml /tmp/*.txt /tmp/uid342; kubectl delete deployment yw-web yw-api yw-old-web -n $NS --ignore-not-found --wait=true --timeout=90s >/dev/null 2>&1; kubectl delete service yw-svc yw-old-svc -n $NS --ignore-not-found >/dev/null 2>&1; kubectl delete configmap yw-cfg yw-old-cfg yw-keep -n $NS --ignore-not-found >/dev/null 2>&1; kubectl delete pod yw-pod -n $NS --ignore-not-found --grace-period=1 --wait=true --timeout=90s >/dev/null 2>&1; cat > /tmp/stack.yaml <<''EOF''\\napiVersion: v1\\nkind: ConfigMap\\nmetadata:\\n  name: yw-old-cfg\\ndata:\\n  MODE: old\\n---\\napiVersion: v1\\nkind: Service\\nmetadata:\\n  name: yw-old-svc\\nspec:\\n  ports:\\n  - port: 80\\n    targetPort: 80\\n  selector:\\n    app: yw-old-web\\n  type: ClusterIP\\n---\\napiVersion: apps/v1\\nkind: Deployment\\nmetadata:\\n  creationTimestamp: null\\n  labels:\\n    app: yw-old-web\\n  name: yw-old-web\\nspec:\\n  replicas: 1\\n  selector:\\n    matchLabels:\\n      app: yw-old-web\\n  strategy: {}\\n  template:\\n    metadata:\\n      creationTimestamp: null\\n      labels:\\n        app: yw-old-web\\n    spec:\\n      containers:\\n      - image: nginx\\n        name: nginx\\n        resources: {}\\nstatus: {}\\nEOF\\nkubectl apply -n $NS -f /tmp/stack.yaml >/dev/null; kubectl create configmap yw-keep -n $NS --from-literal=KEEP=1 >/dev/null; kubectl rollout status deployment/yw-old-web -n $NS --timeout=90s >/dev/null 2>&1; true"]', '["sh", "-c", "( ! kubectl get deployment yw-old-web -n $NS >/dev/null 2>&1 ) && ( ! kubectl get service yw-old-svc -n $NS >/dev/null 2>&1 ) && ( ! kubectl get configmap yw-old-cfg -n $NS >/dev/null 2>&1 ) && ( kubectl get configmap yw-keep -n $NS >/dev/null 2>&1 ) && ( grep -Eq ''^kind: Deployment$'' /tmp/stack.yaml )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "Deployment yw-old-web 이 지워졌다", "cmd": ["sh", "-c", "! kubectl get deployment yw-old-web -n $NS >/dev/null 2>&1"]}, {"label": "Service yw-old-svc 가 지워졌다", "cmd": ["sh", "-c", "! kubectl get service yw-old-svc -n $NS >/dev/null 2>&1"]}, {"label": "ConfigMap yw-old-cfg 가 지워졌다", "cmd": ["sh", "-c", "! kubectl get configmap yw-old-cfg -n $NS >/dev/null 2>&1"]}, {"label": "다른 ConfigMap yw-keep 은 남아 있다", "cmd": ["sh", "-c", "kubectl get configmap yw-keep -n $NS >/dev/null 2>&1"]}, {"label": "파일은 그대로 있다", "cmd": ["sh", "-c", "grep -Eq ''^kind: Deployment$'' /tmp/stack.yaml"]}]', '[{"title": "kubectl 치트 시트", "url": "https://kubernetes.io/docs/reference/kubectl/quick-reference/"}, {"title": "kubectl explain", "url": "https://kubernetes.io/docs/reference/kubectl/generated/kubectl_explain/"}, {"title": "선언형 설정 파일로 오브젝트 관리", "url": "https://kubernetes.io/docs/tasks/manage-kubernetes-objects/declarative-config/"}, {"title": "디플로이먼트", "url": "https://kubernetes.io/docs/concepts/workloads/controllers/deployment/"}, {"title": "컨피그맵", "url": "https://kubernetes.io/docs/concepts/configuration/configmap/"}]'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 342 AND order_index = 11);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 342, 12, 'YAML 로 작업하는 순서', 'YAML 파일로 Deployment 를 만들고 고쳐 가는 한 사이클을 순서대로 놓아 보세요.', '뼈대를 먼저 만들고, 고치고, 적용 전에 미리 보고, 적용하고, 결과를 확인하는 순서예요.', NULL, NULL, '[]', 'order', '["`kubectl apply -f 파일` 로 클러스터에 적용한다", "`kubectl diff -f 파일` 로 바뀔 내용을 미리 확인한다", "`kubectl create deployment ... --dry-run=client -o yaml > 파일` 로 뼈대를 만든다", "`sed` 나 편집기로 replicas·라벨·env·resources 를 고친다", "`kubectl get deployment` 로 원하는 상태가 됐는지 확인한다"]', NULL, '먼저 `--dry-run=client -o yaml` 로 뼈대를 파일로 만들고, 그 파일을 고칩니다. `kubectl diff -f` 로 적용했을 때 무엇이 바뀌는지 미리 보면 실수를 줄일 수 있고, 마음에 들면 `apply -f` 로 적용한 뒤 `get` 으로 결과를 확인합니다. 파일이 원하는 상태의 기록으로 남아 같은 파일로 반복해서 적용할 수 있어요.', '[2, 3, 1, 0, 4]', NULL, NULL, NULL
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 342 AND order_index = 12);

